/* From Uiverse.io by Javierrocadev - Tags: card, animated, batman */
.__UIV_SCOPE__ .card {
  width: 370px;
  height: 270px;
  background: linear-gradient(120deg, rgba(255,237,57,1) 0%, rgba(247,253,45,1) 100%);
  ;
  position: relative;
  display: flex;
  justify-content: center;
  padding: 20px;
  border-radius: 15px;
  transition: all 0.5s ease;
}

.__UIV_SCOPE__ .card::before {
  content: 'Dart';
  position: absolute;
  width: 0px;
  height: 60px;
  border-left: 30px solid #3A486F;
  border-right: 30px solid #3A486F;
  border-bottom: 10px solid transparent;
  top: -10px;
  left: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 8px;
  text-transform: uppercase;
  transition: all 0.5s ease;
}

.__UIV_SCOPE__ .svg-icon {
  width: 5em;
  height: 5em;
  fill: #3A486F;
}

.__UIV_SCOPE__ .svgContainer {
  height: 100px;
  width: 100px;
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .svgContainer svg {
  position: absolute;
  overflow: visible;
}

.__UIV_SCOPE__ .dartboard {
  width: 2em;
  height: 2em;
  padding: 6px;
  border: 3px solid #3A486F;
  border-radius: 50%;
  transition: all 0.5s ease;
  transform: scale(2) rotate(34deg);
}

.__UIV_SCOPE__ .eyehole {
  transform: scale(1.2) rotate(-270deg);
  transition: all 0.5s ease;
}

.__UIV_SCOPE__ .batman {
  transition: all .4s ease-in;
  transform: rotate(55deg) translate(240px, -45px) scale(1.2);
}

.__UIV_SCOPE__ .svg-fill-primary {
  fill: #242424;
}

.__UIV_SCOPE__ .card-info {
  display: flex;
  flex-direction: column;
  justify-content: end;
  text-align: center;
  gap: 10px;
  align-items: center;
}

.__UIV_SCOPE__ .card span {
  font-size: 20px;
  font-weight: 700;
  text-transform: uppercase;
}

.__UIV_SCOPE__ .card-info p {
  color: #3A486F;
  font-weight: 600;
}

.__UIV_SCOPE__ .card-info .challengeButton {
  text-decoration: none;
  background-color: #343434;
  color: white;
  padding: 5px 15px;
  border-radius: 10px;
  box-sizing: border-box;
  transition: all 0.5s ease;
}

.__UIV_SCOPE__ .card:hover {
  box-shadow: 10px 10px 15px 0px rgba(0,0,0,0.83);
}

.__UIV_SCOPE__ .card:hover .batman {
  transform: rotate(-50deg) translate(12px, 2px);
}

.__UIV_SCOPE__ .card:hover .eyehole {
  transform: scale(1);
}

.__UIV_SCOPE__ .card:hover .dartboard {
  transform: scale(1) rotate(0deg) translate(0, 0);
}

.__UIV_SCOPE__ .challengeButton:hover {
  background-color: #3A486F;
}

.__UIV_SCOPE__ .card:hover::before {
  border-left: 30px solid #182445;
  border-right: 30px solid #182445;
  border-bottom: 10px solid transparent;
  top: -15px;
}
